"""The artifact (Run 7, block U): open() on one fresh clean ResNet and one fresh clean Z113 — the seven cells with their status, from Runs 4–7 files."""
import sys, os, json, glob
os.environ.setdefault('WB_DEV', 'cpu')
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np
J = lambda p: json.load(open(p)) if os.path.exists(p) else {}
X, K, P5R, P5Z, RR, S6, S7 = J('results/run7/X.json'), J('results/run7/K.json'), J('results/run7/P5_resnet.json'), J('results/run7/P5_z113.json'), J('results/run7/R.json'), J('results/run6/score.json'), J('results/run7/score.json')
