def cell(tag, status, text): print(f"  {tag:<28} [{status:^10}] {text}")
print('=' * 120); print('open(ResNet-18, CIFAR-10, clean + augmentation, seed 5)  — r6_resnet_cleanaug_s5'); k = 'r6_resnet_cleanaug_s5'
lam = X[k]['lambda_']['penultimate']; learned = X[k]['learned_penultimate']
cell('P1 what it learned', 'registered', f"learned symmetries (architecture subtracted, λ ≥ 0.5 at the penultimate layer): {learned}; λ = " + ', '.join(f"{f} {lam[f]['lambda_']:+.2f}" for f in learned) + f"; contrastive search recovers {X[k]['contrastive'][0]['nearest']} (|cos| {abs(X[k]['contrastive'][0]['cosine']):.2f}); partially learned by augmentation: shift {lam['shift_circular']['lambda_']:+.2f}, flip {lam['hflip']['lambda_']:+.2f}; made MORE sensitive: noise {lam['gaussian_noise']['lambda_']:+.2f}, blur {lam['gaussian_blur']['lambda_']:+.2f}, jpeg {lam['jpeg']['lambda_']:+.2f}")
cell('P2 why this decision', 'registered', f"orbit coherence under the learned group on CIFAR-10 test: κ_s mean {K[k]['in_kappa_s_mean']:.3f} (untrained network {K[k]['untrained_kappa_s_mean']:.3f}); on its own training set κ median {R6[k]['K']['train_kappa_median']:.2f} vs memorisers 0.23")
cell('P3 spurious structure', 'carried', "functional floor + dominance rule are Z113 instruments (Run 4); on the CNN: shift consistency 0.989 (train recipe), no slot structure to read")
cell('P4 what it does not know', 'FAIL' if not S7.get("K'.2", {}).get('PASS') else 'PASS', f"κ_s over learned symmetries, AUROC: SVHN {K[k]['svhn']['auroc_kappa_s_learned']:.3f} (built-in group {K[k]['svhn']['auroc_kappa_s_builtin_run6']:.3f}, max-softmax {K[k]['svhn']['auroc_msp']:.3f}); CIFAR-100 {K[k]['cifar100']['auroc_kappa_s_learned']:.3f} ({K[k]['cifar100']['auroc_kappa_s_builtin_run6']:.3f}, {K[k]['cifar100']['auroc_msp']:.3f}); lowest-κ images misclassified {100*K[k]['lowest_frac_misclassified']:.0f}%")
a, b = P5R[k]['a'], P5R[k]['b']; cell('P5 where it will fail', 'PASS' if (a['auroc_kappa_s_learned'] > a['auroc_msp'] or b['auroc_kappa_s_learned'] > b['auroc_msp']) else 'FAIL', f"natural failure: test errors AUROC κ_s {a['auroc_kappa_s_learned']:.3f} vs msp {a['auroc_msp']:.3f} (non-learned null {a['auroc_kappa_s_nonlearned']:.3f}); 25 corruption cells pooled κ_s {b['auroc_kappa_s_learned']:.3f} vs msp {b['auroc_msp']:.3f}")
cell('P6 understands?', 'registered', f"shift consistency {R6[k]['P6_b']['shift_consistency']:.3f} (memorisers 0.17–0.19); learned-symmetry count {len(learned)} (memorisers 0); depth slope: no difference once the label-blind null is removed (transformer-only instrument)")
cell('P7 how it formed', 'not measured', 'formation sweeps exist for Z113 only; the CNN has no discrete group to watch appear')
print('=' * 120); print('open(Z113 transformer, clean, seed 12)  — r6_z113_clean_s12'); k = 'r6_z113_clean_s12'; z = Z6[k]
cell('P1 what it learned', 'registered', f"the cyclic group generated by translation by {z['u']} (full 113-cycle from outputs alone); characters at {RR[k]['frequencies_cycle_coord']}; swap is built-in (untrained q 0.03) and kept; the symmetric translation (a+u, b−u) is a learned invariance (λ_post +0.74), the orbit translation is a symmetry, not an invariance (λ −0.40)")
cell('P2 why this decision', 'registered', f"orbit coherence κ = 1.000 on held-out inputs (memorisers 0.000); rebuilt from generator + characters with 11 weights: {RR[k]['rebuilt_acc']:.4f} held-out accuracy")
cell('P3 spurious structure', 'registered', f"slot shares (a, b, hint) = ({z['slot_share'][0]:.3f}, {z['slot_share'][1]:.3f}, {z['slot_share'][2]:.3f}); dominance flag none; functional interrupt (Run 4) 5/5")
cell('P4 what it does not know', 'partial', f"OOV token: κ AUROC {z['K']['oov']['auroc_kappa']:.3f} (max-softmax {z['K']['oov']['auroc_msp']:.3f}); pairs from a smaller modulus are valid inputs and are not detected (0.50)")
p = P5Z.get('r7_z113_clean_s20', {}); cell('P5 where it will fail', 'PASS' if S7.get("P5'.Z", {}).get('PASS') else 'FAIL', f"natural failure on an early-stopped sibling (seed 20, test acc {p.get('test_acc', 0):.2f}): AUROC κ {p.get('auroc_kappa', 0):.3f} vs max-softmax {p.get('auroc_msp', 0):.3f}; adversarial radius (Runs 1–6): nothing beats the margin")
cell('P6 understands?', 'registered', f"slot collapse yes; q(swap) {z['q_swap']:.3f}; null-subtracted depth slope {z['connection']['delta']:+.3f}; generator yes → UNDERSTANDS 4/4 (memorisers 0/4)")
sw = sorted(J(f'results/run6/sweep_{k}.json'), key=lambda x: x['ckpt']); g = sw[0]['jump_ckpt']; c1 = [x['ckpt'] for x in sw if x['full_cycle']][0]
cell('P7 how it formed', 'registered', f"generator first accepted at checkpoint {c1} (test acc {[x for x in sw if x['ckpt'] == c1][0]['test_acc']:.2f}), largest jump at {g}, lead {g - c1:+d}; persistence {S7['P7']['persistence'][k]:.3f} (≥ 0.85)")
